AThirdPersonMPCharacter::MoveForward(float Value)		{		if ((Controller != nullptr) && (Value != 0.0f))		{			// 找出向前的道路			
const FRotator Rotation = Controller->GetControlRotation();			const FRotator YawRotation(0, Rotation.Yaw, 0); 			// 获取向前矢量			const FVector Direction = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);			AddMovementInput(Direction, Value);		}	} 	void AThirdPersonMPCharacter::MoveRight(float Value)	{		if ( (Controller != nullptr) && (Value != 0.0f) )		{			// 找出正确的道路			const FRotator Rotation = Controller->GetControlRotation();			const FRotator YawRotation(0, Rotation.Yaw, 0); 			// 获取正确的矢量			const FVector Direction = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);			// add movement in that direction			AddMovementInput(Direction, Value);		}	} 	//////////////////////////////////////////////////////////////////////////	// 复制的属性 	void AThirdPersonMPCharacter::GetLifetimeReplicatedProps(TArray <FLifetimeProperty>& OutLifetimeProps) const	{		Super::GetLifetimeReplicatedProps(OutLifetimeProps); 		//Replicate current health.		DOREPLIFETIME(AThirdPersonMPCharacter, CurrentHealth);	} 	void AThirdPersonMPCharacter::OnHealthUpdate()	{		//客户端特定的功能		if (IsLocallyControlled())		{			FString healthMessage = FString::Printf(TEXT("You now have %f health remaining."), CurrentHealth);			GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Blue, healthMessage); 			if (CurrentHealth <= 0)			{				FString deathMessage = FString::Printf(TEXT("You have been killed."));				GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red, deathMessage);			}		} 		//服务器特定的功能		if (GetLocalRole() == ROLE_Authority)		{			FString healthMessage = FString::Printf(TEXT("%s now has %f health remaining."), *GetFName().ToString(), CurrentHealth);			GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Blue, healthMessage);		} 		//在所有机器上都执行的函数。		/*			因任何因伤害或死亡而产生的特殊功能都应放在这里。		*/	} 	void AThirdPersonMPCharacter::OnRep_CurrentHealth()	{		OnHealthUpdate();	} 	void AThirdPersonMPCharacter::SetCurrentHealth(float healthValue)	{		if (GetLocalRole() == ROLE_Authority)		{			CurrentHealth = FMath::Clamp(healthValue, 0.f, MaxHealth);			OnHealthUpdate();		}	} 	float AThirdPersonMPCharacter::TakeDamage(float DamageTaken, struct FDamageEvent const& DamageEvent, AController* EventInstigator, AActor* DamageCauser)	{		float damageApplied = CurrentHealth - DamageTaken;		SetCurrentHealth(damageApplied);		return damageApplied;	} 	void AThirdPersonMPCharacter::StartFire()	{		if (!bIsFiringWeapon)	{			bIsFiringWeapon = true;			UWorld* World = GetWorld();			World->GetTimerManager().SetTimer(FiringTimer, this, &AThirdPersonMPCharacter::StopFire, FireRate, false);			HandleFire();	}	} 	void AThirdPersonMPCharacter::StopFire()	{		bIsFiringWeapon = false;	} 	void AThirdPersonMPCharacter::HandleFire_Implementation()		{		FVector spawnLocation = GetActorLocation() + (GetActorRotation().Vector() * 100.0f) + (GetActorUpVector() * 50.0f);		FRotator spawnRotation = GetActorRotation(); 		FActorSpawnParameters spawnParameters;		spawnParameters.Instigator = GetInstigator();		spawnParameters.Owner = this; 		AThirdPersonMPProjectile* spawnedProjectile = GetWorld()->SpawnActor<AThirdPersonMPProjectile>(spawnLocation, spawnRotation, spawnParameters);	}
