float rpDen = max((etaI * cosT) + (etaT * cosI), 1e-6);
float rs = ((etaI * cosI) - (etaT * cosT)) / rsDen;
float rp = ((etaI * cosT) - (etaT * cosI)) / rpDen;
float reflectance = saturate(0.5 * (rs * rs + rp * rp));

