void ACustomPawn::FindAndSetmyHUD()
{
	// set myHUD
	APlayerController* PlayerController = UGameplayStatics::GetPlayerController(GetWorld(), 0);
	myHUD = Cast<ACustomHUD>(PlayerController->GetHUD());
```

